                break;
            }
        }
        self.expect(ast::Token::CloseParen)?;
        Ok(ast::Statement::CreateTable { name, columns })
    }

    /// Parses a CREATE TABLE column definition.
    fn parse_create_table_column(&mut self) -> Result<ast::Column> {
        let name = self.next_ident()?;
        let datatype = match self.next_if_keyword() {
            Some(Keyword::Boolean | Keyword::Bool) => DataType::Boolean,
            Some(Keyword::Integer | Keyword::Int) => DataType::Integer,
            Some(Keyword::Float | Keyword::Double) => DataType::Float,
            Some(Keyword::String | Keyword::Text | Keyword::Varchar) => DataType::String,
            Some(k) => return errinput!("unexpected datatype keyword {k}"),
            None => return errinput!("expected datatype"),
        };

